	// 获取角色策略
	GetRolePolicies(context.Context, *v12.Str) (*v12.StrArray, error)
	// 获取私有角色策略
	GetPrivateRolePolicies(context.Context, *v12.Str) (*v12.StrArray, error)
	// 给私有角色添加策略
	AddPrivateRolePolicies(context.Context, *RolePoliciesRequest) (*v12.Bool, error)
	// 给私有角色删除策略
	DelPrivateRolePolicies(context.Context, *RolePoliciesRequest) (*v12.Bool, error)
