	GetRoleStaffs(context.Context, *RoleRequest) (*StaffPortalMultiReply, error)
	// 更新角色的员工
	UpdateRoleStaff(context.Context, *RoleStaffRequest) (*v12.Bool, error)
	// 删除角色的员工
	DelRoleStaff(context.Context, *RoleStaffRequest) (*v12.Bool, error)
	// 添加角色的员工
	AddRoleStaff(context.Context, *RoleStaffRequest) (*v12.Bool, error)
	// [免鉴权] 获取上传凭证
	GetUploadCredential(context.Context, *v13.GetUploadCredentialByMicroRequest) (*v13.GetUploadCredentialReply, error)
	// [免鉴权] 获取字典选项
	GetDictionaryOptions(context.Context, *OneDictionaryByNameRequest) (*OptionsReply, error)
